package com.cryptostrategy.platform.evaluation.internal;
import com.cryptostrategy.platform.backtesting.api.model.*;import java.math.*;
public final class MetricCalculator {private static final int SCALE=10;public Metrics calculate(BacktestResult result){BigDecimal initial=result.initialCapital().value();if(initial.signum()<=0)throw new IllegalArgumentException("Initial capital must be positive");BigDecimal total=result.finalCapital().value().subtract(initial).divide(initial,SCALE,RoundingMode.HALF_EVEN);long wins=result.trades().stream().filter(t->t.realizedPnl().signum()>0).count();BigDecimal win=result.trades().isEmpty()?BigDecimal.ZERO.setScale(SCALE):BigDecimal.valueOf(wins).divide(BigDecimal.valueOf(result.trades().size()),SCALE,RoundingMode.HALF_EVEN);var e=result.equityCurveSummary();BigDecimal drawdown=e.peakEquity().value().signum()==0?BigDecimal.ZERO.setScale(SCALE):e.peakEquity().value().subtract(e.troughEquity().value()).divide(e.peakEquity().value(),SCALE,RoundingMode.HALF_EVEN);return new Metrics(total,win,drawdown,result.trades().size());}public record Metrics(BigDecimal totalReturn,BigDecimal winRate,BigDecimal maximumDrawdown,int numberOfTrades){}}
